    const MEMORY: [AttachmentShape; 1] = [AttachmentShape {
        kind: MEMORY_KIND,
        rights: MEMORY_READ_TRANSFER,
    }];

    #[test]
    fn exact_little_endian_body_requires_its_own_interface_and_direction() {
        for value in [0, 1, 0x01020304, u32::MAX] {
            let request = Request { value }.encode();
            let response = Response { value }.encode();
            assert_eq!(&request[..4], b"CE\x01\x01");
            assert_eq!(&request[4..], &value.to_le_bytes());
            assert_eq!(validate_request(&request, &MEMORY), Ok(Request { value }));
            assert_eq!(
                validate_response(&response, &MEMORY),
                Ok(Response { value })
            );
            assert_eq!(
                validate_request(&response, &MEMORY),
                Err(DecodeError::Opcode)
            );
            assert_eq!(
                validate_response(&request, &MEMORY),
                Err(DecodeError::Opcode)
            );
            assert_eq!(
                Request::decode(&crate::echo::Request { value }.encode()),
                Err(DecodeError::Magic)
            );
            assert_eq!(
                crate::echo::Request::decode(&request),
                Err(crate::echo::DecodeError::Magic)
            );
        }
    }

    #[test]
    fn all_malformed_body_lengths_and_header_bits_reject_before_handler() {
        let bytes = Request { value: u32::MAX }.encode();
        let called = Cell::new(0);
        for i in 0..4 {
            for bit in 0..8 {
                let mut bad = bytes;
                bad[i] ^= 1 << bit;
                assert!(
                    server_dispatch(&bad, &MEMORY, |r| {
                        called.set(called.get() + 1);
                        Response { value: r.value }
                    })
                    .is_err()
                );
            }
        }
        for length in 0..WIRE_BYTES {
            assert_eq!(
                validate_request(&bytes[..length], &MEMORY),
                Err(DecodeError::Length)
            );
            assert_eq!(
                validate_response(&bytes[..length], &MEMORY),
                Err(DecodeError::Length)
            );
        }
        let mut long = [0; WIRE_BYTES + 1];
        long[..WIRE_BYTES].copy_from_slice(&bytes);
        assert_eq!(validate_request(&long, &MEMORY), Err(DecodeError::Length));
        assert_eq!(validate_response(&long, &MEMORY), Err(DecodeError::Length));
        assert_eq!(called.get(), 0);
    }

    #[test]
    fn count_kind_and_all_excess_or_missing_rights_reject_before_handler() {
        let bytes = Request { value: 7 }.encode();
        let called = Cell::new(false);
        for shapes in [&[][..], &[MEMORY[0], MEMORY[0]][..]] {
            assert_eq!(
                server_dispatch(&bytes, shapes, |_| {
                    called.set(true);
                    Response { value: 7 }
                }),
                Err(DecodeError::CapabilityCount)
            );
        }
        for kind in 0..=u8::MAX {
            let shape = [AttachmentShape {
                kind,
                rights: MEMORY_READ_TRANSFER,
            }];
            assert_eq!(
                validate_request(&bytes, &shape).is_ok(),
                kind == MEMORY_KIND
            );
        }
        for rights in 0..=u16::MAX {
            let shape = [AttachmentShape {
                kind: MEMORY_KIND,
                rights,
            }];
            if rights != MEMORY_READ_TRANSFER {
                assert_eq!(
                    server_dispatch(&bytes, &shape, |_| {
                        called.set(true);
                        Response { value: 7 }
                    }),
                    Err(DecodeError::CapabilityRights)
                );
            }
        }
        // READ|REVOKE is 129, a different authority shape from READ|TRANSFER65.
        // Keep this concrete regression independent of the symbolic happy path.
        assert_eq!(
            server_dispatch(
                &bytes,
                &[AttachmentShape {
                    kind: 1,
                    rights: 129
                }],
                |_| {
                    called.set(true);
                    Response { value: 7 }
                }
            ),
            Err(DecodeError::CapabilityRights)
        );
        assert!(!called.get());
    }

    #[test]
    fn arbitrary_wire_and_metadata_are_total_with_exact_shape_only() {
        let mut state = 0x91e10da5u32;
        for _ in 0..8192 {
            let mut bytes = [0; WIRE_BYTES];
            for byte in &mut bytes {
                state ^= state << 13;
                state ^= state >> 17;
                state ^= state << 5;
                *byte = state as u8;
            }
            let shape = [AttachmentShape {
                kind: state as u8,
                rights: (state >> 8) as u16,
            }];
            let exact = shape == MEMORY;
            assert_eq!(
                validate_request(&bytes, &shape).is_ok(),
                exact && &bytes[..4] == b"CE\x01\x01"
            );
            assert_eq!(
                validate_response(&bytes, &shape).is_ok(),
                exact && &bytes[..4] == b"CE\x01\x02"
            );
            // Exercise every arbitrary payload under both valid headers as well.
            let value = u32::from_le_bytes(bytes[4..].try_into().unwrap());
            assert_eq!(
                validate_request(&Request { value }.encode(), &MEMORY),
                Ok(Request { value })
            );
            assert_eq!(
                validate_response(&Response { value }.encode(), &MEMORY),
                Ok(Response { value })
            );
        }
    }

    #[derive(Debug, PartialEq, Eq)]
    struct LinearCapability(u64);

    #[derive(Clone, Copy)]
    enum Mode {
        Returned,
        Rejected,
        Recovered,
        Delivered,
        Invalidated,
        Pending,
        Invalid,
        Indeterminate,
    }

    struct FakeTransport {
        mode: Mode,
        observed: Option<([u8; WIRE_BYTES], u64, u64)>,
        calls: usize,
    }

    impl SyncTransport for FakeTransport {
        type Capability = LinearCapability;
        type Recovery = u64;
        type Error = u64;

        fn call(
            &mut self,
            request: [u8; WIRE_BYTES],
            capability: LinearCapability,
            absolute_deadline: u64,
        ) -> TransportOutcome<LinearCapability, u64, u64> {
            self.observed = Some((request, capability.0, absolute_deadline));
            self.calls += 1;
            match self.mode {
                Mode::Returned => TransportOutcome::Returned {
                    bytes: Response { value: 7 }.encode(),
                    capability,
                },
                Mode::Rejected => TransportOutcome::Rejected {
                    error: 1,
                    original: capability,
                },
                Mode::Recovered => TransportOutcome::QueuedFailure {
                    error: 4,
                    recovered: capability,
                },
                Mode::Delivered => TransportOutcome::DeliveredFailure { error: 4 },
                Mode::Invalidated => TransportOutcome::QueuedInvalidated { error: 7 },
                Mode::Pending => TransportOutcome::QueuedPending {
                    error: 8,
                    recovery: 123,
                },
                Mode::Invalid => TransportOutcome::Returned {
                    bytes: request,
                    capability,
                },
                Mode::Indeterminate => TransportOutcome::Indeterminate { error: 999 },
            }
        }
    }

    #[test]
    fn typed_client_preserves_distinct_linear_ownership_outcomes() {
        for mode in [
            Mode::Returned,
            Mode::Rejected,
            Mode::Recovered,
            Mode::Delivered,
            Mode::Invalidated,
            Mode::Pending,
            Mode::Invalid,
            Mode::Indeterminate,
        ] {
            let mut transport = FakeTransport {
                mode,
                observed: None,
                calls: 0,
            };
            let outcome = client_call(&mut transport, 7, LinearCapability(512), 12345);
            match mode {
                Mode::Returned => assert_eq!(
                    outcome,
                    ClientOutcome::Returned {
                        response: Response { value: 7 },
                        capability: LinearCapability(512)
                    }
                ),
                Mode::Rejected => assert_eq!(
                    outcome,
                    ClientOutcome::Rejected {
                        error: 1,
                        original: LinearCapability(512)
                    }
                ),
                Mode::Recovered => assert_eq!(
                    outcome,
                    ClientOutcome::QueuedFailure {
                        error: 4,
                        recovered: LinearCapability(512)
                    }
                ),
                Mode::Delivered => {
                    assert_eq!(outcome, ClientOutcome::DeliveredFailure { error: 4 })
                }
                Mode::Invalidated => {
                    assert_eq!(outcome, ClientOutcome::QueuedInvalidated { error: 7 })
                }
                Mode::Pending => assert_eq!(
                    outcome,
                    ClientOutcome::QueuedPending {
                        error: 8,
                        recovery: 123
                    }
                ),
                Mode::Invalid => assert_eq!(
                    outcome,
                    ClientOutcome::InvalidReply {
                        error: DecodeError::Opcode,
                        returned: LinearCapability(512)
                    }
                ),
                Mode::Indeterminate => {
                    assert_eq!(outcome, ClientOutcome::Indeterminate { error: 999 })
                }
            }
            assert_eq!(transport.calls, 1);
            assert_eq!(
                transport.observed,
                Some((Request { value: 7 }.encode(), 512, 12345))
            );
        }
    }

